"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3718],{5216(e){e.exports=JSON.parse('{"title":"Vercel\uc640 Cloudflare Workers \ubca4\uce58\ub9c8\ud06c \ub9ac\ubdf0","date":"2025-10-21","coverUrl":"/kudzu-based-bench/assets/notion/ea43e55c1b536a0d.png","html":"<h1 data-notion-block-id=\\"28de548d-8a8e-802d-b7d4-e54186a1203a\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"291e548d-8a8e-8031-8d38-c84381c662c1\\" id=\\"291e548d-8a8e-8031-8d38-c84381c662c1\\">Vercel\uc640 Cloudflare Workers \ubca4\uce58\ub9c8\ud06c \ub9ac\ubdf0</h2><a href=\\"https://blog.cloudflare.com/unpacking-cloudflare-workers-cpu-performance-benchmarks/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/unpacking-cloudflare-workers-cpu-performance-benchmarks/</a><p data-notion-block-id=\\"28de548d-8a8e-8013-a5e3-ca60b82c85c3\\">Vercel\uacfc Cloudflare Workers\uc758 \ubca4\uce58\ub9c8\ud06c\uc5d0 \ub300\ud574\uc11c Cloudflare\uce21\uc774 \uc778\ud504\ub77c\uc5d0\uc11c \uc131\ub2a5 \ud5a5\uc0c1\uc744 \ud558\uac70\ub098, \ubca4\uce58\ub9c8\ud06c\uac00 \uc798\ubabb\ub41c \ubd80\ubd84\uc744 \uc218\uc815\ud588\ub2e4\ub294 \ucde8\uc9c0\uc758 \uae00\uc785\ub2c8\ub2e4. \uc5b8\ub73b\ubcf4\uba74 \uc778\uc0ac\uc774\ud2b8\ub97c \uc5bb\uae30 \ud798\ub4e4\uc9c0\ub9cc, \uc131\ub2a5\uc744 \ub290\ub9ac\uac8c\ud558\ub294 Next.js\ub098 Node.js\uc758 \uc138\ud305, \uc131\ub2a5 \ubb38\uc81c\ub97c \ud30c\uace0\ub4dc\ub294 \ubc95, \ub610\ud55c \ucf54\ub4dc\uc5d0\uc11c\uac00 \uc544\ub2c8\ub77c \uc778\ud504\ub77c \ub808\ubca8\uc5d0\uc11c\ub3c4 \uc131\ub2a5 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud560 \uc218\ub3c4 \uc788\ub2e4\ub294 \uc810, \ubca4\uce58\ub9c8\ud06c\uc758 \uc5ed\uc124\u2026 \ub4f1\uc744 \uc5ec\ub7ec\uac00\uc9c0 \ubb38\uc81c\uc810\ub4e4\uc744 \uc5ff\ubcfc \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 Cloudflare\uce21\uc758 \ubca4\uce58\ub9c8\ud06c \ucd94\uc801 \uae00\uc744 \ub530\ub77c\uac00\ubcf4\uba74\uc11c \uc774\ub97c \ud6d1\uc5b4\ubcf4\ub294 \uac83\ub3c4 \uc88b\uc544\ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"292e548d-8a8e-809b-8f4d-f9803060922b\\" id=\\"292e548d-8a8e-809b-8f4d-f9803060922b\\">Node.js\uc5d0\uc11c \ud30c\uc77c IO\uc5d0 \ucd5c\uc2e0 \ubc84\uc804 \ud65c\uc6a9\ud558\uae30</h2><a href=\\"https://nodejsdesignpatterns.com/blog/reading-writing-files-nodejs/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodejsdesignpatterns.com/blog/reading-writing-files-nodejs/</a><p data-notion-block-id=\\"292e548d-8a8e-8002-ab27-e22c6880b772\\">Node.js\ub97c \uc0ac\uc6a9\ud558\ub2e4\ubcf4\uba74 promise\uae30\ubc18 API\ub098 deprecated API\ub97c \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ud30c\uc77c \uc77d\uae30/\uc4f0\uae30\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ucd5c\uc2e0 \ubc84\uc804\uc5d0\uc11c \uad8c\uc7a5\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \ud558\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/117edf84-09ae-4b59-a977-3278116eb17f#05d2a6bf-9690-4f4f-b082-2d82e2b22b85\\">Node.js\ub97c \uc798 \uc4f0\ub294 9\uac00\uc9c0 \ubc95\uce59</a>\ub3c4 \uac19\uc774 \uc77d\uc5b4\ubcfc\ub9cc \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"28ee548d-8a8e-8046-a0d8-c19798d2e091\\" id=\\"28ee548d-8a8e-8046-a0d8-c19798d2e091\\">\ubc18\uc751\uc131\uc774 \uc88b\uc740 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4</h2><a href=\\"https://outbox.matthewphillips.info/archive/perils-of-reactivity\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://outbox.matthewphillips.info/archive/perils-of-reactivity</a><p data-notion-block-id=\\"28ee548d-8a8e-8058-ab0c-ee826be70ca9\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/1a3e548d-8a8e-801a-8b68-e2f5142b0aad#1a3e548d-8a8e-80fe-83dd-f79165f784ec\\">Svelte5, \uba85\uacfc \uc554</a>\uc5d0\uc11c \ub2e4\ub918\ub4ef\uc774, React\uc5d0\uc11c\uc758 \ubc18\uc751\uc131 \ubfd0\ub9cc \uc544\ub2c8\ub77c, \ub9ce\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc758 \ubc18\uc751\uc131\uc740 \ub514\ubc84\uae45 \ubc0f \ud504\ub808\uc784\uc6cc\ud06c\uc758 \ub3d9\uc791 \ubc29\uc2dd\uc744 \ubc30\uc6b0\uac8c \ub9cc\ub4e7\ub2c8\ub2e4. \ubb3c\ub860 \uc800\uc790\uc758 \\"\ubc18\uc751\uc131\uc758 \uc88b\uc740 \uc544\ud0a4\ud14d\uccd0 \ub300\uccb4\uc81c\uac00 \uc788\ub2e4\\"\ub77c\ub294 \uac83\uc740 \uc57d\uac04\uc758 \uacfc\uc7a5\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0\ub9cc, \ubc18\uc751\uc131(Reactivity)\uc774 \ud56d\uc0c1 \uc88b\uc740 \uac83\ub9cc\uc774 \uc544\ub2c8\ub77c\ub294 \uad00\uc810\uc740 \uc783\uc9c0 \ub9d0\uc544\uc57c \uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"292e548d-8a8e-80ab-ae3a-d9da70135382\\" id=\\"292e548d-8a8e-80ab-ae3a-d9da70135382\\">\uc9c1\ub82c\ud654/\uc5ed\uc9c1\ub82c\ud654 \ube44\uc6a9 \uc904\uc774\uae30</h2><a href=\\"https://www.orilivni.com/2025/10/serialization-and-deserialization/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.orilivni.com/2025/10/serialization-and-deserialization/</a><p data-notion-block-id=\\"291e548d-8a8e-8048-b652-da14e8ab3e30\\">\uc9c1\ub82c\ud654/\uc5ed\uc9c1\ub82c\ud654 \ube44\uc6a9 \uc904\uc774\ub294 \ubc29\ubc95\uc744 \ucc3e\uc544\uc11c \uc5ec\ub7ec\uac00\uc9c0 \ubc29\ubc95\uc744 \uc2dc\ub3c4\ud574\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. useSyncExternalStore\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\uc740 \uac1c\ubc1c\uc790\ub4e4\uc5d0\uac8c \uc775\uc219\ud560\uc9c0\ub3c4 \ubaa8\ub974\uc9c0\ub9cc, \uae00\uc5d0\uc11c \uc81c\uc2dc\ud558\ub294 \uacbd\uc6b0, \uc774\uc678\uc5d0\ub3c4 \uc5ec\ub7ec \uacbd\uc6b0\uc5d0 \ub530\ub77c\uc11c\ub294 \ube44\uc6a9\uc774 \ub9ce\uc774 \ubc1c\uc0dd\ud560 \uc218\ub3c4 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c\ub824\uc8fc\uace0, \uc774 \ub54c \uc5b4\ub5bb\uac8c \ub300\ucc98\ud574\uc57c \ud558\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"291e548d-8a8e-8013-a3a5-fd4cda6f3e95\\" id=\\"291e548d-8a8e-8013-a3a5-fd4cda6f3e95\\">React Conf 2025 \ub3cc\uc544\ubcf4\uae30</h2><a href=\\"https://blog.swmansion.com/react-conf-2025-recap-922c50d97318\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.swmansion.com/react-conf-2025-recap-922c50d97318</a><p data-notion-block-id=\\"291e548d-8a8e-8071-9e41-f09ad9a585c9\\">React Conf 2025\uc5d0\uc11c \ubc1c\ud45c\ub41c \ub0b4\uc6a9 \uc911 \uc8fc\ubaa9\ud560 \ubd80\ubd84\uc744 \ubaa8\uc740 \uae00\uc785\ub2c8\ub2e4. React\uc758 \ub9ce\uc740 \uae30\ub2a5\uacfc \ub3c4\uad6c\ub4e4\uc774 \ucd94\uac00\ub418\uc5c8\uc73c\ub2c8, \uaf2d \ubcf4\uc2dc\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"28de548d-8a8e-80ef-b177-eb59653ba494\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"290e548d-8a8e-807a-a110-cccfe316beae\\" id=\\"290e548d-8a8e-807a-a110-cccfe316beae\\">\ub54c\ub85c\ub294 \uc678\ubd80 \ub3c4\uad6c \uc5c6\uc774 \uc131\ub2a5 \ud5a5\uc0c1\uc774 \uac00\ub2a5\ud558\ub2e4.</h2><a href=\\"https://joist-orm.io/blog/lazy-fields/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://joist-orm.io/blog/lazy-fields/</a><p data-notion-block-id=\\"291e548d-8a8e-8081-bc81-fbb0278c3269\\">\ucf54\ub4dc\uc758 \uc131\ub2a5 \ud5a5\uc0c1\uc744 \uc704\ud574 \ubcf4\ud1b5 codegen\uc774\ub098 AST \ud30c\uc2f1\uc744 \ud1b5\ud55c transform\uc744 \ud558\uae30 \ub9c8\ub828\uc778\ub370, \uadf8\ub7f0 \ubc29\ubc95\uc744 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uace0 JS \ud504\ub85c\ud1a0\ud0c0\uc785\uc73c\ub85c \uc5b4\ub5bb\uac8c \uc131\ub2a5 \ud5a5\uc0c1\uc744 \uc774\ub8e8\uc5b4\ub0c8\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"291e548d-8a8e-8058-9dc9-fa86db0aef9c\\" id=\\"291e548d-8a8e-8058-9dc9-fa86db0aef9c\\">CSS Grid \uba58\ud0c8\ubaa8\ub378 \uc774\ud574\ud558\uae30</h2><a href=\\"https://webkit.org/blog/17474/css-grid-a-helpful-mental-model-and-the-power-of-grid-lines/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webkit.org/blog/17474/css-grid-a-helpful-mental-model-and-the-power-of-grid-lines/</a><h2 data-notion-block-id=\\"292e548d-8a8e-803f-b04e-d3cdc36943e6\\" id=\\"292e548d-8a8e-803f-b04e-d3cdc36943e6\\">GraphQL\uc5d0 \ub300\ud55c \ubbf8\uc2e0</h2><a href=\\"https://www.jovidecroock.com/blog/graphql-myths/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jovidecroock.com/blog/graphql-myths/</a><h2 data-notion-block-id=\\"290e548d-8a8e-80a2-ade7-dd442b9e5f92\\" id=\\"290e548d-8a8e-80a2-ade7-dd442b9e5f92\\">\uc65c <code>null</code>\uc740 <code>object</code>\uc77c\uae4c</h2><a href=\\"https://pzarycki.com/en/posts/js-null/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://pzarycki.com/en/posts/js-null/</a><h2 data-notion-block-id=\\"292e548d-8a8e-80d7-9a6d-e5d5e864d5fe\\" id=\\"292e548d-8a8e-80d7-9a6d-e5d5e864d5fe\\"><code>&#x3C;output></code>\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4</h2><a href=\\"https://denodell.com/blog/html-best-kept-secret-output-tag\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://denodell.com/blog/html-best-kept-secret-output-tag</a><h1 data-notion-block-id=\\"28de548d-8a8e-8011-99ed-e249317ba2ce\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://bun.sh/blog/bun-v1.3\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://bun.sh/blog/bun-v1.3</a><p data-notion-block-id=\\"28ee548d-8a8e-80c5-9af2-ff1b34c8b456\\">Bun 1.3\uc73c\ub85c \ub4e4\uc5b4\uc624\uba74\uc11c \uc5ec\ub7ec\uac00\uc9c0 \uc0ac\uc6a9\uc790 \ud3b8\uc758 \uae30\ub2a5, \ub2e4\ub978 \uc11c\ube44\uc2a4(SQL, Redis)\uc640 \ud1b5\ud569\ud558\ub294 \uae30\ub2a5 \ub4f1 \uc5ec\ub7ec \uc8fc\ubaa9\ud560 \ub9cc\ud55c \uae30\ub2a5\uc774 \ucd9c\uc2dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://v3.nitro.build/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://v3.nitro.build/</a><p data-notion-block-id=\\"290e548d-8a8e-803e-bab8-c5ea04b5ca30\\">NitroJS\uac00 3\ubc84\uc804\uc744 \ucd9c\uc2dc\ud558\uba74\uc11c Vite \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub798\ud551\ud558\ub294 \ubc29\uc2dd\uc5d0\uc11c Vite \ud50c\ub7ec\uadf8\uc778 \ubc29\uc2dd\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://voidzero.dev/posts/announcing-vite-plus\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://voidzero.dev/posts/announcing-vite-plus</a><p data-notion-block-id=\\"292e548d-8a8e-8071-a9ec-f811fd56b800\\">Vite\ub97c \ube4c\ub4dc \ud234\ub85c \ub450\uc9c0 \uc54a\uace0 Vite\ub97c \ub118\uc5b4\uc120 \uc5ec\ub7ec \uae30\ub2a5\ub4e4\uc744 \ud1b5\ud569\ud55c Vite+\ub97c \uc900\ube44 \uc911\uc5d0 \uc788\ub2e4\uace0 \ud558\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://midscenejs.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://midscenejs.com/</a><p data-notion-block-id=\\"292e548d-8a8e-8026-b66c-f7438288633b\\">AI\ub97c \uae30\ubc18\uc73c\ub85c \uc790\uc5f0\uc5b4 UI \ud14c\uc2a4\ud305 \uc790\ub3d9\ud654\ub97c \ud574\uc8fc\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4.</p>"}')}}]);